  "📉 {0} seni kadrodan çıkardı. Kariyer bitmedi, ama yeniden inşa etmen lazım.": "📉 {0} исключил вас из ростера. Карьера не окончена, но придётся всё строить заново.",
  "📈 Artık bir “{0}” dövüşçüsüsün. UCC maaşını yeniden düzenlemek istiyor.": "📈 Теперь вы боец уровня «{0}». UCC хочет пересмотреть ваши гонорары.",
  "📜 {0} kontratın bitti. Menajerinin telefonu susmuyor.": "📜 Ваш контракт с {0} закончился. Телефон менеджера не умолкает.",
  "📞 Telefon çaldı. Arayan: Dean Wyatt. “Seni izliyorum evlat. Challenger Series’e gel, kendini göster.”": "📞 Зазвонил телефон. Это Дин Уайетт. «Я слежу за тобой, парень. Приезжай на Challenger Series и покажи, на что способен».",
