  "Ailenden biri. Güvenilir ama sektörü tanımıyor.": "Семья. Надёжен, но не знает бизнеса.",
  "Selim Kaptan": "Капитан Селим",
  "Bölgesel organizasyonlarla sıkı ilişkiler.": "Крепкие связи с региональными лигами.",
