  "— {0}. RAUNT — Sen: {1}": "— РАУНД {0} — Вы: {1}",
  "🧠 {0} bu hamleyi bekliyordu. Aynı oyunu {1}. kez oynamak seni öngörülebilir yapıyor.": "🧠 {0} ждал этого. Одно и то же ({1} раз подряд) делает вас предсказуемым.",
  "🔥 {0} üstüne çullanıyor, son yumruk {1} dövüşçüsünü kafesin zeminine gömüyor! NAKAVT!": "🔥 {0} набрасывается, финальный удар вбивает {1} в настил! НОКАУТ!",
  "🔥 {0} yağmur gibi yumruk indiriyor, {1} karşılık veremiyor, hakem araya giriyor! TKO!": "🔥 {0} осыпает ударами, {1} не отвечает, рефери вмешивается! ТКО!",
  "😱 {0} umutsuz bir kontra savurdu ve TAM İSABET! Durum tersine döndü!": "😱 {0} выбросил отчаянную контратаку и ПОПАЛ ТОЧНО! Всё перевернулось!",
  "{0} bir şekilde ayakta kaldı, zili bekliyor. Sen de çok yoruldun.": "{0} каким-то чудом стоит, дожидаясь гонга. Вы тоже выжаты.",
  "🎯 {0} hedef seçerek vuruyor, sağ-sol-sağ… hakem yeter diyor! TKO!": "🎯 {0} выбирает удары, правый-левый-правый… рефери достаточно! ТКО!",
  "{0} kontrollü vuruşlarla puan topluyor, rakip toparlanmaya çalışıyor.": "{0} набирает очки контролируемыми ударами, пока соперник приходит в себя.",
  "{0} yere indirmek için daldı ama rakip son gücüyle savundu. Fırsat kaçtı.": "{0} пошёл на тейкдаун, но соперник защитился из последних сил. Шанс упущен.",
  "🔨 {0} yerde mount aldı, ground and pound yağdırıyor, hakem durdurdu! TKO!": "🔨 {0} занял маунт в партере, засыпает ударами, рефери остановил! ТКО!",
  "🔒 {0} sersem rakibin sırtını aldı ve {1} ile tap attırdı!": "🔒 {0} взял спину оглушённого соперника и заставил сдаться: {1}!",
  "{0} yerde ağır vuruyor ama {1} bir şekilde hayatta kalıyor.": "{0} наносит тяжёлые удары в партере, но {1} как-то выживает.",
  "🔥 İnanılmaz! Sarsılmışken savurduğun sağ el {0} dövüşçüsünü de sarstı!": "🔥 Невероятно! Правый, выброшенный в нокдауне, потряс и {0}!",
  "Rakibine sarıldın, kafanı yasladın. Saniyeler geçiyor… toparlanıyorsun.": "Вы вошли в клинч и уперлись головой. Секунды идут… вы восстанавливаетесь.",
  "Ayakların seni taşıdı. Kafes boyunca dönüp mesafe açtın, kafan netleşiyor.": "Ноги держат. Вы обошли октагон и разорвали дистанцию, в голове проясняется.",
  "Karşılık vermeye çalıştın, isabet etmedi ama o da bitiremedi. Hayattasın!": "Вы пытались ответить, не попали, но и он не добил. Вы выжили!",
  "💀 {0} son darbeyi indirdi. Bilinçsiz yere yığıldın. NAKAVT.": "💀 {0} нанёс финальный удар. Вы рухнули без сознания. НОКАУТ.",
  "💀 {0} yumruk yağdırıyor, kendini savunamıyorsun. Hakem durdurdu. TKO.": "💀 {0} осыпает ударами, вы не можете защищаться. Рефери остановил. ТКО.",
  "Ağır darbeler aldın ama ayaktasın. Zil seni kurtarmak zorunda.": "Вы пропустили тяжёлые удары, но всё ещё стоите. Спасти может только гонг.",
  "🔒 {0} {1} kilidini sonuna kadar sıktı… {2} TAP ATTI!": "🔒 {0} дожал «{1}» до конца… {2} СДАЛСЯ!",
  "{0} son anda {1} kilidinden sıyrıldı ve ayağa kalktı!": "{0} в последний момент выскользнул из «{1}» и встал!",
  "{0} riske girmiyor, üstte kalıp dirsek ve yumrukla puan topluyor.": "{0} действует надёжно: остаётся сверху и набирает очки локтями и ударами.",
  "Tap attın. {0} {1} ile kazandı. Acı ama sağlıklısın.": "Вы сдались. {0} победил: {1}. Больно, но вы целы.",
  "Elleri kontrol ettin, açıyı kırdın ve {0} kilidinden çıktın!": "Вы проконтролировали руки, сломали угол и выбрались из «{0}»!",
  "Patlayıcı bir köprüyle sıyrıldın ve üste geçtin! Seyirci çıldırıyor!": "Вы вырвались взрывным мостом и оказались сверху! Публика сходит с ума!",
  "🦴 Tap atmayı reddettin… bir çıtırtı. Hakem durdurdu. {0} {1} ile kazandı.": "🦴 Вы отказались сдаваться… хруст. Рефери остановил. {0} победил: {1}.",
  "Kilidi açamadın. {0} {1} ile seni tap attırdı.": "Вы не смогли вырваться. {0} заставил вас сдаться: {1}.",
  "🔔 {0}. raunt bitti.": "🔔 Раунд {0} окончен.",
  "🩺 Ringside doktoru kesiğe bakıp başını salladı. Maç durduruldu. Doktor kararıyla TKO.": "🩺 Врач посмотрел на рассечение и покачал головой. Бой остановлен. ТКО по решению врача.",
  "🏳️ {0} köşesi havlu attı! Rakip raunda çıkamıyor. TKO!": "🏳️ Угол {0} выбросил полотенце! Соперник не выходит на раунд. ТКО!",
