  "\"Zayıf noktası {0}. Oraya git!\"": "«Его слабое место — {0}. Туда!»",
  "\"{0} tarafını zorla, orada çöküyor.\"": "«Дави через {0}, там он ломается».",
  "\"Hep {0} yapıyorsun, adam seni okudu! Bu raunt başka bir şey dene.\"": "«Ты всё время делаешь „{0}“, он тебя прочитал! В этом раунде попробуй другое».",
  "\"Seni çözdü! Ritmi değiştir, başka bir şey göster.\"": "«Он тебя раскусил! Смени ритм, покажи новое».",
  "\"Aynı kaseti çalıyorsun. Onu şaşırt!\"": "«Ты крутишь ту же пластинку. Удиви его!»",
  "\"Aynı şeyi tekrar yaparsan seni okur. Onu şaşırt.\"": "«Сделаешь то же самое — он прочитает. Удиви».",
  "\"Tahmin edilebilir olma. Karıştır.\"": "«Не будь предсказуемым. Меняй».",
  "\"Nefesin gitmiş! Tempoyu düşür, akıllı dövüş.\"": "«Ты сдох! Сбавь темп, дерись умно».",
  "\"Ağzın açık nefes alıyorsun, sakin! Ayaklarını kullan.\"": "«Дышишь ртом, успокойся! Работай ногами».",
