  "Amatör ligde resmi sıralama yok. Profesyonel olduğunda organizasyonunun sıklet sıralaması burada açılacak.": "В любительской лиге нет официального рейтинга. Когда станете профи, здесь появится рейтинг вашего дивизиона.",
  "Bu organizasyonda sıralama yok. Tek gecelik bir fırsat: kazanırsan kapılar açılır.": "У этой лиги нет рейтинга. Шанс одной ночи: победите — и двери откроются.",
