  "🔒 TAP! {0} kilidin içinde tap attı. Submission!": "🔒 СДАЛСЯ! {0} постучал в захвате. Болевой!",
  "🔒 Kilitten çıkamadın… tap attın.": "🔒 Не смог выбраться из захвата… ты сдался.",
